package com.primehr.succession;
import com.primehr.succession.domain.*;import org.junit.jupiter.api.Test;import java.time.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class SuccessionDevelopmentDomainTest{
 @Test void planRequiresIncludedDecisionAndCandidateOwnsAcknowledgment(){var d=decision(SuccessionPoolDecision.Outcome.INCLUDED);var c=candidate();var p=new SuccessionDevelopmentPlan("A",d,c,"Prepare for target role",LocalDate.of(2027,1,1),LocalDate.of(2027,12,31),LocalDate.of(2027,4,1));p.activate("PANEL-1",Instant.parse("2027-01-02T00:00:00Z"));assertThatThrownBy(()->p.acknowledge("OTHER",null,Instant.now())).isInstanceOf(IllegalArgumentException.class);p.acknowledge("EMP-1","I acknowledge with comments",Instant.parse("2027-01-03T00:00:00Z"));assertThat(p.getAcknowledgmentStatus()).isEqualTo(SuccessionDevelopmentPlan.AcknowledgmentStatus.RESPONSE_SUBMITTED);}
 @Test void milestoneCompletionRequiresEvidenceAndCannotBeOverwritten(){var m=new SuccessionDevelopmentMilestone("A","plan","Complete coaching","Observed target behavior",LocalDate.of(2027,3,1),1);assertThatThrownBy(()->m.updateStatus(SuccessionDevelopmentMilestone.Status.COMPLETED,null,"Done",null,"PANEL",Instant.now())).isInstanceOf(IllegalArgumentException.class);m.updateStatus(SuccessionDevelopmentMilestone.Status.COMPLETED,"EVIDENCE-1","Done",null,"PANEL",Instant.now());assertThatThrownBy(()->m.updateStatus(SuccessionDevelopmentMilestone.Status.IN_PROGRESS,null,null,null,"PANEL",Instant.now())).isInstanceOf(IllegalStateException.class);}
 @Test void reviewRecommendationDoesNotCreateOrChangeMembership(){var r=new SuccessionDevelopmentReview("A","plan",1,LocalDate.of(2027,4,1),SuccessionDevelopmentReview.Recommendation.REMOVE_FROM_POOL,"Review outcome","Restricted reason","PANEL",Instant.now(),null);assertThat(r.getRecommendation()).isEqualTo(SuccessionDevelopmentReview.Recommendation.REMOVE_FROM_POOL);assertThat(r.getEmployeeVisibleSummary()).isEqualTo("Review outcome");}
 @Test void membershipLineageEnforcesRemovalAndReinstatementTransitions(){var active=SuccessionPoolMembershipEvent.activate("A",decision(SuccessionPoolDecision.Outcome.INCLUDED),"HEAD",Instant.now());var removed=active.transition(SuccessionPoolMembershipEvent.EventType.REMOVED,LocalDate.of(2027,3,1),active.getExpiresOn(),"Removed after review","Restricted","HEAD",Instant.now());assertThat(removed.getResultingStatus()).isEqualTo(SuccessionPoolMembershipEvent.ResultingStatus.REMOVED);var reinstated=removed.transition(SuccessionPoolMembershipEvent.EventType.REINSTATED,LocalDate.of(2027,4,1),LocalDate.of(2027,12,31),"Reinstated after correction","Restricted","HEAD",Instant.now());assertThat(reinstated.getResultingStatus()).isEqualTo(SuccessionPoolMembershipEvent.ResultingStatus.ACTIVE);assertThatThrownBy(()->removed.transition(SuccessionPoolMembershipEvent.EventType.EXPIRED,LocalDate.of(2027,12,31),null,"Expired","Restricted","HEAD",Instant.now())).isInstanceOf(IllegalStateException.class);}
 private static SuccessionPoolDecision decision(SuccessionPoolDecision.Outcome outcome){var d=mock(SuccessionPoolDecision.class);when(d.getId()).thenReturn("decision");when(d.getAssessmentId()).thenReturn("assessment");when(d.getCandidateId()).thenReturn("candidate");when(d.getOutcome()).thenReturn(outcome);when(d.getReadinessLevelCode()).thenReturn("READY");when(d.getEffectiveFrom()).thenReturn(LocalDate.of(2027,1,1));when(d.getExpiresOn()).thenReturn(LocalDate.of(2027,12,31));when(d.getEmployeeVisibleReason()).thenReturn("Included");when(d.getRestrictedRationale()).thenReturn("Panel rationale");return d;}
 private static SuccessionCandidate candidate(){var c=mock(SuccessionCandidate.class);when(c.getEmployeeNo()).thenReturn("EMP-1");when(c.getEmployeeName()).thenReturn("Employee One");when(c.getTargetPositionName()).thenReturn("Target Position");return c;}
}
